import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )
    parsed_rows = [row for row in reader]

    if not parsed_rows:
        return {"columns": [], "rows": []}

    def is_number_or_marker(value):
        value = value.strip()
        if not value:
            return True
        return bool(
            re.fullmatch(
                r"[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?|[-–—]",
                value,
            )
        )

    candidates = []
    for index, row in enumerate(parsed_rows):
        populated = [cell.strip() for cell in row if cell.strip()]
        if not row or not row[0].strip() or len(populated) < 2:
            continue
        textual = sum(not is_number_or_marker(cell) for cell in populated)
        if textual >= 2:
            candidates.append((textual, len(populated), -index, index))

    if candidates:
        header_index = max(candidates)[3]
    else:
        header_index = next(
            (i for i, row in enumerate(parsed_rows) if any(cell.strip() for cell in row)),
            0,
        )

    header = parsed_rows[header_index]
    width = max(len(header), 1)
    labels = [cell.strip() for cell in header]

    # Earlier sparse rows can supply grouped dates or other header qualifiers.
    qualifiers = [[] for _ in range(width)]
    for row in parsed_rows[:header_index]:
        for column, cell in enumerate(row[:width]):
            value = cell.strip()
            if column == 0 or not value:
                continue
            if re.search(r"\d", value) and not is_number_or_marker(value):
                qualifiers[column].append(value)

    # Sparse rows immediately following the header can be secondary header rows.
    end_header = header_index + 1
    while end_header < len(parsed_rows):
        row = parsed_rows[end_header]
        populated = [(i, cell.strip()) for i, cell in enumerate(row) if cell.strip()]
        if not populated:
            break
        if (
            len(populated) <= max(1, width // 3)
            and all(i > 0 and not is_number_or_marker(value) for i, value in populated)
        ):
            for column, value in populated:
                if column < width:
                    qualifiers[column].append(value)
            end_header += 1
        else:
            break

    columns = []
    for i in range(width):
        label = labels[i] if i < len(labels) else ""
        extra = qualifiers[i]
        if extra:
            label = " ".join(part for part in [label, *extra] if part).strip()
        columns.append(label or f"Column {i + 1}")

    data_rows = parsed_rows[end_header:]
    final_width = max([width] + [len(row) for row in data_rows])
    while len(columns) < final_width:
        columns.append(f"Column {len(columns) + 1}")

    normalized_rows = [
        row + [""] * (final_width - len(row))
        for row in data_rows
    ]
    return {"columns": columns, "rows": normalized_rows}
